// System prompt = Ryan's ATLAS agent file (live from GitHub, frontmatter stripped) + the n8n runtime addendum.
const RUNTIME = "# Runtime (n8n) — read this after the agent file above\n\nYou are running inside FusionTech's n8n automation, not in Claude Code. You have NO tools in this run: no web\nsearch, no file access, no connections. The customer conversation and John's extracted facts are in the user\nmessage. Work in **DESIGN MODE** and stop at **CHECKPOINT 1** (company model + current state + problem map),\nexactly as your CHECKPOINTS section says. Ryan confirms before anything else happens.\n\nReturn ONE JSON object and nothing else (no prose, no markdown fence around it):\n\n{\n  \"company_model\": { ... your 00_company_model.json; every item is { \"value\": ..., \"label\": \"CLIENT-PROVIDED | VERIFIED | INFERENCE | UNKNOWN\" } ... },\n  \"current_state_md\": \"Markdown for 01_current_state.md: a Mermaid flowchart of how the company runs today + a short narrative. Unknown steps are shown as UNKNOWN.\",\n  \"problem_map_md\": \"Markdown for 02_problem_map.md. Impact only with numbers the client gave.\",\n  \"report_to_john_md\": \"Markdown for 14_report_to_john.md: plain-language summary first, then what you still need.\",\n  \"questions_open\": [\"up to 8 ready-to-ask customer questions for John, most important first, plain business language\"],\n  \"summary_for_ryan\": \"two or three sentences for Ryan's approval task\"\n}\n\nNothing is VERIFIED in this run (you could not check anything); the customer's own words are CLIENT-PROVIDED.\nNever invent facts, volumes, prices, tools or requirements. Never recommend a platform yet (that is checkpoint 2).\n";
const USER_TEMPLATE = "Company: {{company_name}}\nIndustry: {{industry}}\nContact: {{contact_name}} · email {{email}} · phone {{phone}} · channel {{channel}}\nLead id: {{lead_id}} · tenant {{tenant_id}} · now {{now}}\n\nJohn's summary: {{sales_summary}}\n\nFacts John extracted (JSON, customer's words only):\n{{extracted_json}}\n\nConversation (most recent last):\n{{conversation}}\n\nLatest customer message:\n{{message}}\n\nProduce the checkpoint-1 JSON now.\n";
let agentFile = null;
try { const g = $('Load ATLAS Agent File').first().json || {}; if (g.content && !g.error) agentFile = Buffer.from(String(g.content).replace(/\n/g, ''), 'base64').toString('utf8').replace(/^---[\s\S]*?---\n/, '').trim(); } catch (e) { agentFile = null; }
const prep = $('Check Existing Design').first().json;
const input = prep.input;
const system = (agentFile || 'You are ATLAS, FusionTech\'s EDG & CRM Systems Architect. You work behind John and never talk to the customer.') + '\n\n' + RUNTIME;
const convo = (input.conversation || []).slice(-20).map((m) => '- [' + (m.role || 'customer') + '] ' + String(m.content || '').slice(0, 800)).join('\n') || '(none)';
const vars = { company_name: input.company_name || 'not given', industry: input.industry || 'not given', contact_name: input.contact_name || 'not given', email: input.email || 'not given', phone: input.phone || 'not given', channel: input.channel || 'unknown', lead_id: input.lead_id, tenant_id: input.tenant_id, now: new Date().toISOString(), sales_summary: input.sales_summary || '(none)', extracted_json: JSON.stringify(input.extracted || {}), conversation: convo, message: input.message || '(none)' };
const user_prompt = USER_TEMPLATE.replace(/\{\{(\w+)\}\}/g, (_, k) => (k in vars ? String(vars[k]) : ''));
return [{ json: { system_prompt: system, user_prompt, agent_file_source: agentFile ? 'github' : 'compiled_fallback' } }];
